#!/usr/bin/env python3
from pathlib import Path

ROOT = Path.cwd()
OBJ = ROOT / 'src/stars_ai/objective_production.py'
INTENT = ROOT / 'src/stars_ai/fleet_intent.py'
TEST = ROOT / 'tests/test_remote_mining_pressure_policy.py'


def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f'{label}: expected exactly one match, found {count}')
    return text.replace(old, new, 1)


def insert_before_once(text, marker, addition, label):
    count = text.count(marker)
    if count != 1:
        raise RuntimeError(f'{label}: expected exactly one marker, found {count}')
    return text.replace(marker, addition + marker, 1)

obj = OBJ.read_text(encoding='utf-8')

old_import = 'from .territorial_defense import assess_territorial_defense\n'
new_import = old_import + 'from .planet_economy import decode_race_economy, working_mineral_reserve\n'
if 'decode_race_economy, working_mineral_reserve' not in obj:
    obj = replace_once(obj, old_import, new_import, 'objective_production imports')

helper_marker = '\ndef plan_objective_ship_builds(state,plan=None):\n'
helpers = '''\n\nREMOTE_MINING_MIN_TURN = 20\nREMOTE_MINING_LATE_TURN = 30\nREMOTE_MINING_REAL_PRESSURE_RATIO = 0.25\nREMOTE_MINING_SEVERE_PRESSURE_RATIO = 0.50\n\n\ndef _is_alternate_reality(state) -> bool:\n    race=getattr(state,"race",None)\n    native=getattr(race,"native",{}) or {}\n    try:\n        prt_id=int(native.get("prt_id",-1))\n    except (TypeError,ValueError):\n        prt_id=-1\n    prt=str(getattr(race,"primary_trait","") or "").casefold()\n    return prt_id==8 or "alternate reality" in prt\n\n\ndef _remote_mining_pressure_policy(state,plan,remote_targets) -> dict:\n    # Remote miners are a capital-intensive mid/late-game tool. Merely seeing\n    # a rich rock is not enough to build them. The empire must be mature and\n    # materially below the shared working-mineral reserve used by economics.\n    owned=[p for p in state.planets if p.owner==state.player_id]\n    turn=max(0,int(state.year)-2400)\n    phase=str(getattr(plan,"phase","") or "")\n    late_phase=phase in {\n        "industrial_buildout","fortification","opportunistic_war","tech_acceleration",\n    }\n    economy=decode_race_economy(state.race)\n\n    surface={"ironium":0,"boranium":0,"germanium":0}\n    reserve={"ironium":0,"boranium":0,"germanium":0}\n    stressed_worlds=0\n    per_world=[]\n    for planet in owned:\n        need=working_mineral_reserve(planet,economy,())\n        world_surface={\n            "ironium":max(0,int(getattr(planet,"ironium",0) or 0)),\n            "boranium":max(0,int(getattr(planet,"boranium",0) or 0)),\n            "germanium":max(0,int(getattr(planet,"germanium",0) or 0)),\n        }\n        short={k:max(0,int(need.get(k,0) or 0)-world_surface[k]) for k in surface}\n        if sum(short.values())>0:\n            stressed_worlds+=1\n        for k in surface:\n            surface[k]+=world_surface[k]\n            reserve[k]+=max(0,int(need.get(k,0) or 0))\n        per_world.append({\n            "planet_id":int(planet.id),\n            "surface":world_surface,\n            "working_reserve":{k:int(need.get(k,0) or 0) for k in surface},\n            "deficit":short,\n        })\n\n    deficits={k:max(0,reserve[k]-surface[k]) for k in surface}\n    reserve_total=max(1,sum(reserve.values()))\n    deficit_total=sum(deficits.values())\n    pressure_ratio=deficit_total/reserve_total\n    critical_deficit=max(deficits.values()) if deficits else 0\n\n    mature=bool(\n        turn>=REMOTE_MINING_MIN_TURN\n        and (late_phase or len(owned)>=6 or turn>=REMOTE_MINING_LATE_TURN)\n    )\n    real_pressure=bool(\n        mature\n        and (\n            pressure_ratio>=REMOTE_MINING_REAL_PRESSURE_RATIO\n            or (\n                stressed_worlds>=max(2,(len(owned)+2)//3)\n                and critical_deficit>=120\n            )\n        )\n    )\n    severe_pressure=bool(\n        real_pressure and pressure_ratio>=REMOTE_MINING_SEVERE_PRESSURE_RATIO\n    )\n    is_ar=_is_alternate_reality(state)\n\n    if not real_pressure:\n        desired=0\n    elif is_ar and turn>=REMOTE_MINING_LATE_TURN:\n        # AR late-game doctrine: once real pressure exists, build a fleet rather\n        # than one or two token miners for homeworld remote-mining leverage.\n        desired=min(16,max(6,6+int(round(pressure_ratio*10))))\n    else:\n        target_count=len(remote_targets)\n        base=min(5,max(1,(target_count+1)//2)) if target_count else 0\n        desired=min(6,base+(2 if severe_pressure else 0))\n\n    return {\n        "turn":turn,\n        "phase":phase,\n        "alternate_reality":is_ar,\n        "mature_empire":mature,\n        "real_mineral_pressure":real_pressure,\n        "severe_mineral_pressure":severe_pressure,\n        "pressure_ratio":round(float(pressure_ratio),3),\n        "surface_stock":surface,\n        "working_reserve":reserve,\n        "reserve_deficit":deficits,\n        "stressed_worlds":stressed_worlds,\n        "owned_worlds":len(owned),\n        "observed_remote_targets":len(remote_targets),\n        "desired_miners":int(desired),\n        "world_diagnostics":per_world,\n        "policy":(\n            "Do not build remote miners merely because rich targets are visible. "\n            "Require a mature empire plus real working-reserve mineral pressure. "\n            "Late-game AR may scale to a large homeworld mining fleet after that gate opens."\n        ),\n    }\n\n\n'''
if '_remote_mining_pressure_policy(' not in obj:
    obj = insert_before_once(obj, helper_marker, helpers, 'objective_production helper insertion')

old_miner = '''    mt=[]\n    for p in state.planets:\n        c=(p.native or {}).get('mineral_concentrations')\n        if p.owner is None and p.observed and c and len(c)>=3 and all(v is not None for v in c[:3]) and sum(max(0,int(v)) for v in c[:3])>=150:\n            mt.append(p)\n    desired_miners=min(3,max(1,math.ceil(len(mt)/2))) if mt else 0; miner_assets=_role_count(ds,counts,'miner'); miner_gap=max(0,desired_miners-miner_assets)\n    if miner_gap and (d:=_pick(state,'miner')):\n        req.append(BuildRequest('miner',int(d['design_number']),d['name'],min(2,miner_gap),124,\n            f"{len(mt)} strong observed remote-mining targets; desired miners={desired_miners}, available/queued={miner_assets}."))\n'''
new_miner = '''    mt=[]\n    for p in state.planets:\n        c=(p.native or {}).get('mineral_concentrations')\n        if p.owner is None and p.observed and c and len(c)>=3 and all(v is not None for v in c[:3]) and sum(max(0,int(v)) for v in c[:3])>=150:\n            mt.append(p)\n    mining_policy=_remote_mining_pressure_policy(state,plan,mt)\n    state.native["remote_mining_build_policy"]=mining_policy\n    desired_miners=int(mining_policy["desired_miners"])\n    miner_assets=_role_count(ds,counts,'miner')\n    miner_gap=max(0,desired_miners-miner_assets)\n    if miner_gap and (d:=_pick(state,'miner')):\n        build_cap=4 if bool(mining_policy["alternate_reality"]) else 2\n        req.append(BuildRequest(\n            'miner',int(d['design_number']),d['name'],min(build_cap,miner_gap),\n            138 if bool(mining_policy["severe_mineral_pressure"]) else 124,\n            (\n                f"Remote mining authorized by real mineral pressure: pressure ratio="\n                f"{float(mining_policy['pressure_ratio']):.1%}, reserve deficit "\n                f"I/B/G={mining_policy['reserve_deficit']['ironium']}/"\n                f"{mining_policy['reserve_deficit']['boranium']}/"\n                f"{mining_policy['reserve_deficit']['germanium']} kT; "\n                f"{len(mt)} strong observed unowned target(s); desired miners={desired_miners}, "\n                f"available/queued={miner_assets}."\n                + (\n                    " AR late-game doctrine permits a large homeworld mining fleet once "\n                    "the real-pressure gate is open."\n                    if bool(mining_policy["alternate_reality"]) else ""\n                )\n            ),\n        ))\n'''
obj = replace_once(obj, old_miner, new_miner, 'remote miner production block')
OBJ.write_text(obj, encoding='utf-8')

intent = INTENT.read_text(encoding='utf-8')
intent_import = 'from .population_units import COLONY_LOAD_COLONISTS\n'
intent_new_import = intent_import + 'from .expansion_network import evaluate_expansion_network\n'
if 'from .expansion_network import evaluate_expansion_network' not in intent:
    intent = replace_once(intent, intent_import, intent_new_import, 'fleet_intent imports')

old_candidates = '''def _mining_candidates(state: GameState, fleet):\n    ranked=[]\n    for p in state.planets:\n        if p.owner is not None or not p.observed: continue\n        conc=(p.native or {}).get("mineral_concentrations")\n        if not conc or len(conc)<3 or any(v is None for v in conc[:3]): continue\n        mineral_score=sum(max(0,int(v)) for v in conc[:3]); travel=distance(fleet.position,p.position)\n        if not mission_reachable(fleet,p.position,'reposition_for_remote_mining'): continue\n        ranked.append((mineral_score-0.75*travel,p,mineral_score,travel))\n    ranked.sort(key=lambda x:x[0],reverse=True)\n    return ranked\n'''
new_candidates = '''def _is_alternate_reality(state: GameState) -> bool:\n    race=getattr(state,"race",None)\n    native=getattr(race,"native",{}) or {}\n    try:\n        prt_id=int(native.get("prt_id",-1))\n    except (TypeError,ValueError):\n        prt_id=-1\n    prt=str(getattr(race,"primary_trait","") or "").casefold()\n    return prt_id==8 or "alternate reality" in prt\n\n\ndef _ar_homeworld_ids(state: GameState) -> set[int]:\n    if not _is_alternate_reality(state):\n        return set()\n    try:\n        network=evaluate_expansion_network(state)\n        ids={\n            int(hub.planet_id)\n            for hub in network.hubs\n            if int(getattr(hub,"promotion_tier",3) or 3)==0\n        }\n        if ids:\n            return ids\n    except Exception:\n        pass\n    return {\n        int(p.id) for p in state.planets\n        if p.owner==state.player_id and bool((p.native or {}).get("is_homeworld"))\n    }\n\n\ndef _mining_candidates(state: GameState, fleet):\n    ranked=[]\n    ar_homeworlds=_ar_homeworld_ids(state)\n    policy=(state.native or {}).get("remote_mining_build_policy") or {}\n    ar_pressure_open=bool(\n        _is_alternate_reality(state)\n        and int(state.year)-2400>=30\n        and policy.get("real_mineral_pressure",True)\n    )\n    for p in state.planets:\n        is_unowned=bool(p.owner is None)\n        is_ar_homeworld=bool(\n            ar_pressure_open\n            and p.owner==state.player_id\n            and int(p.id) in ar_homeworlds\n        )\n        if (not is_unowned and not is_ar_homeworld) or not p.observed:\n            continue\n        conc=(p.native or {}).get("mineral_concentrations")\n        if not conc or len(conc)<3 or any(v is None for v in conc[:3]): continue\n        mineral_score=sum(max(0,int(v)) for v in conc[:3]); travel=distance(fleet.position,p.position)\n        if not mission_reachable(fleet,p.position,'reposition_for_remote_mining'): continue\n        homeworld_bonus=100 if is_ar_homeworld else 0\n        ranked.append((mineral_score+homeworld_bonus-0.75*travel,p,mineral_score,travel))\n    ranked.sort(key=lambda x:x[0],reverse=True)\n    return ranked\n'''
intent = replace_once(intent, old_candidates, new_candidates, 'mining candidate function')
old_hold = '"reason":"No observed unowned planet with usable mineral-concentration data is known. Do not send a miner to an unknown world."'
new_hold = '"reason":"No eligible observed remote-mining target is known. Normal races require an unowned world; late-game AR may also use its homeworld after the mineral-pressure gate opens. Do not send a miner to an unknown world."'
if old_hold in intent:
    intent = intent.replace(old_hold, new_hold, 1)
INTENT.write_text(intent, encoding='utf-8')

TEST.write_text('''from stars_ai.models import GameState, RaceProfile, Tech, Planet, Fleet, Position\nfrom stars_ai.objective_production import plan_objective_ship_builds\nfrom stars_ai.fleet_intent import _mining_candidates\n\n\ndef _state(year=2405, ar=False, minerals=(1000,1000,1000)):\n    race=RaceProfile()\n    if ar:\n        race.primary_trait="Alternate Reality"\n        race.native={"prt_id":8}\n    dp=[\n        {"design_number":0,"name":"Scout","role":"scout","dry_mass":20,"fuel_capacity":200,"engine_id":3},\n        {"design_number":2,"name":"Colony","role":"colony","dry_mass":60,"fuel_capacity":200,"engine_id":3},\n        {"design_number":5,"name":"Cotton Picker","role":"miner","dry_mass":574,"fuel_capacity":210,"engine_id":3},\n    ]\n    home=Planet(0,"Home",Position(0,0),owner=1,observed=True,habitability=100,population=500000,\n        ironium=minerals[0],boranium=minerals[1],germanium=minerals[2],native={\n            "is_homeworld":True,"has_starbase":True,\n            "starbase_capabilities":{"can_build_ships":True,"can_refuel":True},\n            "mineral_concentrations":[80,80,80]})\n    target=Planet(1,"Rich Rock",Position(20,0),owner=None,observed=True,habitability=-20,\n        native={"mineral_concentrations":[80,80,80]})\n    unknown=[Planet(i,f"U{i}",Position(i,20),owner=None,observed=False) for i in range(2,20)]\n    return GameState("g",year,1,race,Tech(),[home,target,*unknown],[],native={"design_profiles":dp,"production_by_planet":{}})\n\n\ndef test_early_rich_target_does_not_authorize_expensive_remote_miners():\n    s=_state(year=2408,minerals=(0,0,0))\n    requests=plan_objective_ship_builds(s)\n    assert not [r for r in requests if r.role=="miner"]\n    policy=s.native["remote_mining_build_policy"]\n    assert policy["mature_empire"] is False\n    assert policy["real_mineral_pressure"] is False\n    assert policy["desired_miners"] == 0\n\n\ndef test_mature_empire_with_real_reserve_deficit_can_build_remote_miners():\n    s=_state(year=2435,minerals=(0,0,0))\n    requests=plan_objective_ship_builds(s)\n    miners=[r for r in requests if r.role=="miner"]\n    assert miners\n    policy=s.native["remote_mining_build_policy"]\n    assert policy["mature_empire"] is True\n    assert policy["real_mineral_pressure"] is True\n    assert policy["desired_miners"] >= 1\n\n\ndef test_late_game_ar_scales_miner_demand_and_accepts_homeworld_target():\n    s=_state(year=2440,ar=True,minerals=(0,0,0))\n    requests=plan_objective_ship_builds(s)\n    policy=s.native["remote_mining_build_policy"]\n    assert policy["alternate_reality"] is True\n    assert policy["real_mineral_pressure"] is True\n    assert policy["desired_miners"] >= 6\n    assert [r for r in requests if r.role=="miner"]\n    fleet=Fleet(5,"AR Miner",1,Position(0,0),role="miner",native={"ship_count":[0,0,0,0,0,1]})\n    candidates=_mining_candidates(s,fleet)\n    assert candidates\n    assert int(candidates[0][1].id) == 0\n''', encoding='utf-8')

print('Applied remote-mining mineral-pressure patch.')
print('Changed src/stars_ai/objective_production.py')
print('Changed src/stars_ai/fleet_intent.py')
print('Added tests/test_remote_mining_pressure_policy.py')
